40	TopoSortingMode GetTopoSortingStrategy() {
41	  std::string topo_sorting_mode_str;
42	  if ((af::GetContext().GetOption(af::OPTION_TOPOSORTING_MODE, topo_sorting_mode_str) == GRAPH_SUCCESS) &&
43	      (!topo_sorting_mode_str.empty())) {
44	    const int32_t base = 10;
45	    auto topo_sorting_mode = static_cast<TopoSortingMode>(std::strtol(topo_sorting_mode_str.c_str(), nullptr, base));
46	    if ((topo_sorting_mode >= TopoSortingMode::kBFS) && (topo_sorting_mode < TopoSortingMode::kInvalid)) {
47	      GELOGD("topo_sorting_mode: %s", GetTopoSortingModeStr(topo_sorting_mode));
48	      return topo_sorting_mode;
49	    } else {
50	      GELOGW("OPTION_TOPOSORTING_MODE = %s is invalid", topo_sorting_mode_str.c_str());
51	    }
52	  }
53	
54	  if (af::GetContext().GetTrainGraphFlag()) {
55	    GELOGD("train flag is 1, use BFS.");
56	    return TopoSortingMode::kBFS;
57	  }
58	
59	  GELOGD("train flag is 0, use DFS.");
60	  return TopoSortingMode::kDFS;
61	}
