68	void InitNodeStatus(const ConstComputeGraphPtr &compute_graph, std::vector<NodeStatus> &nodes_info) {
69	  nodes_info.clear();
70	  nodes_info.resize(compute_graph->GetDirectNodesSize());
71	  int64_t index = 0;
72	  for (const auto &node : compute_graph->GetDirectNode()) {
73	    nodes_info[index].size = 0;
74	    nodes_info[index].status = WalkStatus::kNotWalked;
75	    node->GetOpDesc()->SetId(index);
76	    index++;
77	  }
78	}
