80	int64_t GetNodeOutputRealSize(const NodePtr &node, std::vector<NodeStatus> &nodes_info) {
81	  int64_t total_size = 0;
82	  if ((node == nullptr) || (node->GetOpDesc() == nullptr)) {
83	    return total_size;
84	  }
85	  NodeStatus &reverse_dfs_node_info = nodes_info[static_cast<size_t>(node->GetOpDesc()->GetId())];
86	  total_size = reverse_dfs_node_info.size;
87	  if (total_size != 0) {
88	    return total_size;
89	  }
90	  for (const auto &out_desc : node->GetOpDescBarePtr()->GetAllOutputsDescPtr()) {
91	    if (out_desc == nullptr) {
92	      continue;
93	    }
94	    int64_t output_size = 0;
95	    (void)af::TensorUtils::CalcTensorMemSize(out_desc->GetShape(), out_desc->GetFormat(), out_desc->GetDataType(),
96	                                             output_size);
97	    total_size += output_size;
98	  }
99	  if (total_size != 0) {
100	    reverse_dfs_node_info.size = total_size;
101	  }
102	  return total_size;
103	}
