106	struct NodeCmp {
107	  explicit NodeCmp(std::vector<NodeStatus> *nodes_info) : nodes_info_(nodes_info) {}
108	  bool operator()(const NodePtr &lhs, const NodePtr &rhs) const {
109	    const auto lhs_size = GetNodeOutputRealSize(lhs, *nodes_info_);
110	    const auto rhs_size = GetNodeOutputRealSize(rhs, *nodes_info_);
111	    if (lhs_size == rhs_size) {
112	      return strcmp(lhs->GetNamePtr(), rhs->GetNamePtr()) > 0;
113	    }
114	    return lhs_size > rhs_size;
115	  }
116	  std::vector<NodeStatus> *nodes_info_;
117	};
