126	struct NodeCmpV2 {
127	  NodeCmpV2(std::vector<NodeStatus> *nodes_info, const std::vector<int64_t> *branch_widths)
128	      : nodes_info_(nodes_info), branch_widths_(branch_widths) {}
129	  bool operator()(const NodePtr &lhs, const NodePtr &rhs) const {
130	    const auto lhs_size = GetNodeOutputRealSize(lhs, *nodes_info_);
131	    const auto rhs_size = GetNodeOutputRealSize(rhs, *nodes_info_);
132	    if (lhs_size == rhs_size) {
133	      const auto lhs_branch = (*branch_widths_)[static_cast<size_t>(lhs->GetOpDesc()->GetId())];
134	      const auto rhs_branch = (*branch_widths_)[static_cast<size_t>(rhs->GetOpDesc()->GetId())];
135	      if (lhs_branch == rhs_branch) {
136	        return strcmp(lhs->GetNamePtr(), rhs->GetNamePtr()) > 0;
137	      }
138	      return lhs_branch < rhs_branch;
139	    }
140	    return lhs_size > rhs_size;
141	  }
142	  std::vector<NodeStatus> *nodes_info_;
143	  const std::vector<int64_t> *branch_widths_;
144	};
