146	template <typename Compare>
147	graphStatus RDFSCoreSort(std::vector<NodePtr> &node_vec, std::vector<NodeStatus> &nodes_info,
148	                         const ConstComputeGraphPtr &compute_graph, const Compare &cmp) {
149	  for (const auto &node : compute_graph->GetDirectNode()) {
150	    if (node->GetOutNodesSize() > 0U) {
151	      continue;
152	    }
153	    std::vector<NodePtr> stack = {node};
154	    while (!stack.empty()) {
155	      const auto current = stack.back();
156	      NodeStatus &info = nodes_info[current->GetOpDesc()->GetId()];
157	      if (info.status == WalkStatus::kNotWalked) {
158	        info.status = WalkStatus::kWalking;
159	        const auto in_all_nodes = current->GetInAllNodes();
160	        std::set<NodePtr, Compare> input_nodes{in_all_nodes.begin(), in_all_nodes.end(), cmp};
161	        stack.insert(stack.end(), input_nodes.cbegin(), input_nodes.cend());
162	        continue;
163	      }
164	      stack.pop_back();
165	      if (info.status == WalkStatus::kWalking) {
166	        info.status = WalkStatus::kWalked;
167	        node_vec.emplace_back(current);
168	      }
169	    }
170	  }
171	  return GRAPH_SUCCESS;
172	}
