174	struct NodeOutInfo {
175	  NodeOutInfo(const NodePtr &node, std::vector<NodeStatus> *nodes_info)
176	      : num_out_data_nodes(node->GetOutDataNodesSize()),
177	        output_size(GetNodeOutputRealSize(node, *nodes_info)),
178	        node_name(node->GetName()) {}
179	
180	  bool operator<(const NodeOutInfo &rhs) const {
181	    if (num_out_data_nodes < rhs.num_out_data_nodes) {
182	      return true;
183	    }
184	    if (num_out_data_nodes > rhs.num_out_data_nodes) {
185	      return false;
186	    }
187	    if (output_size < rhs.output_size) {
188	      return true;
189	    }
190	    if (output_size > rhs.output_size) {
191	      return false;
192	    }
193	    return node_name < rhs.node_name;
194	  }
195	
196	  int64_t num_out_data_nodes;
197	  int64_t output_size;
198	  std::string node_name;
199	};
