207	bool InputIsLongLifeTimeNode(const NodePtr &node, const ConstComputeGraphPtr &graph) {
208	  bool match = false;
209	  for (const auto &in_data_anchor : node->GetAllInDataAnchorsPtr()) {
210	    if (in_data_anchor == nullptr) {
211	      continue;
212	    }
213	    const auto &peer_out_anchor = in_data_anchor->GetPeerOutAnchor();
214	    if (peer_out_anchor == nullptr) {
215	      continue;
216	    }
217	    const auto &peer_node = peer_out_anchor->GetOwnerNode();
218	    if (peer_node == nullptr) {
219	      continue;
220	    }
221	    const bool is_io_data =
222	        ((graph.get() == peer_node->GetOwnerComputeGraphBarePtr()) &&
223	         (OpTypeUtils::IsDataNode(peer_node->GetType()) || OpTypeUtils::IsConstPlaceHolderNode(peer_node->GetType())));
224	    std::string op_type;
225	    if ((!NodeUtils::GetConstOpType(peer_node, op_type)) && (!OpTypeUtils::IsVariableNode(peer_node->GetType())) &&
226	        (!is_io_data)) {
227	      return false;
228	    } else {
229	      match = true;
230	    }
231	    GELOGD("Node:%s peer:%s type :%s", node->GetName().c_str(), peer_node->GetName().c_str(),
232	           peer_node->GetType().c_str());
233	  }
234	  return match;
235	}
