237	///  variable  const
238	///      \    /
239	///   first node
240	///       |
241	///   middle node
242	///       |
243	///   last node
244	///     /  |
245	/// node1  node2
246	graphStatus GetOutNodeIndex(std::vector<NodePtr> &nodes, size_t &index, size_t &out_count,
247	                            const ConstComputeGraphPtr &graph) {
248	  if (nodes.empty()) {
249	    return GRAPH_FAILED;
250	  }
251	
252	  // first node's inputs muse be long life time
253	  if ((nodes.size() == 1U) && (!InputIsLongLifeTimeNode(nodes.front(), graph))) {
254	    return GRAPH_FAILED;
255	  }
256	
257	  const auto &node = nodes.back();
258	  auto op_desc = node->GetOpDesc();
259	  GE_CHECK_NOTNULL(op_desc);
260	  // middle node must be single input
261	  if ((nodes.size() != 1U) && (node->GetAllInDataAnchorsSize() != 1U)) {
262	    return GRAPH_FAILED;
263	  }
264	
265	  int64_t min_index = 0;
266	  Node *delay_node = nullptr;
267	  for (const auto &out_node : node->GetOutAllNodes()) {
268	    out_count++;
269	    GE_CHECK_NOTNULL(out_node);
270	    auto out_node_desc = out_node->GetOpDescBarePtr();
271	    GE_CHECK_NOTNULL(out_node_desc);
272	    GELOGD("Node:%s id:%ld peer node:%s id:%ld", node->GetName().c_str(), op_desc->GetId(),
273	           out_node_desc->GetName().c_str(), out_node_desc->GetId());
274	    if ((min_index == 0) || (out_node_desc->GetId() < min_index)) {
275	      min_index = out_node_desc->GetId();
276	      delay_node = out_node.get();
277	    }
278	  }
279	
280	  if (delay_node != nullptr) {
281	    index = static_cast<size_t>(min_index);
282	    if (index > (static_cast<size_t>(op_desc->GetId()) + 1U)) {
283	      GELOGD("Node:%s id:%ld delay to:%s id:%zu", node->GetName().c_str(), op_desc->GetId(),
284	             delay_node->GetName().c_str(), index);
285	    }
286	    return GRAPH_SUCCESS;
287	  }
288	  return GRAPH_FAILED;
289	}
