291	void DelayTopoSort(std::vector<NodePtr> &nodes, const ConstComputeGraphPtr &graph) {
292	  // pair.first:  this node can be delay or not
293	  // pair.second: delayed nodes to this node
294	  std::vector<std::pair<bool, std::vector<NodePtr>>> delay_nodes;
295	  delay_nodes.resize(nodes.size());
296	
297	  // set init index
298	  for (size_t i = 0U; i < delay_nodes.size(); ++i) {
299	    nodes[i]->GetOpDescBarePtr()->SetId(static_cast<int64_t>(i));
300	    delay_nodes[i].first = true;
301	    delay_nodes[i].second.emplace_back(nodes[i]);
302	  }
303	
304	  // move delayed node to fit node
305	  size_t delay_node_count = 0U;
306	  for (size_t i = 0U; i < delay_nodes.size(); ++i) {
307	    size_t delay_to_index = 0U;
308	    size_t out_count = 0U;
309	    if (delay_nodes[i].first &&
310	        (GetOutNodeIndex(delay_nodes[i].second, delay_to_index, out_count, graph) == GRAPH_SUCCESS) &&
311	        (delay_to_index < delay_nodes.size()) && (delay_to_index > (i + 1U))) {
312	      delay_nodes[delay_to_index].second.insert(delay_nodes[delay_to_index].second.begin(),
313	                                                delay_nodes[i].second.begin(), delay_nodes[i].second.end());
314	      if (out_count > 1U) {
315	        // last node can not be delay
316	        delay_nodes[delay_to_index].first = false;
317	      }
318	      delay_nodes[i].second.clear();
319	      delay_node_count++;
320	    }
321	  }
322	  if (delay_node_count > 0U) {
323	    nodes.clear();
324	    for (size_t i = 0U; i < delay_nodes.size(); ++i) {
325	      if (!delay_nodes[i].second.empty()) {
326	        nodes.insert(nodes.end(), delay_nodes[i].second.begin(), delay_nodes[i].second.end());
327	      }
328	    }
329	    GELOGI("Delay %zu nodes for %s.", delay_node_count, graph->GetName().c_str());
330	  }
331	}
