333	class TopoSortStack {
334	 public:
335	  explicit TopoSortStack(std::vector<NodeStatus> *nodes_info, const bool is_mem_priority = false,
336	                         const bool is_dfs = false, const bool is_reverse_dfs = false)
337	      : is_mem_priority_(is_mem_priority), is_dfs_(is_dfs), is_reverse_dfs_(is_reverse_dfs), nodes_info_(nodes_info) {}
338	
339	  NodePtr Pop() {
340	    if (is_mem_priority_ && (!is_reverse_dfs_)) {
341	      const auto &it = mem_priority_stack_.cbegin();
342	      const NodePtr node = it->second;
343	      (void)mem_priority_stack_.erase(it);
344	      return node;
345	    }
346	    const NodePtr node = normal_stack_.back();
347	    normal_stack_.pop_back();
348	    return node;
349	  }
350	
351	  void Push(const NodePtr &node) {
352	    if (is_mem_priority_ && (!is_reverse_dfs_)) {
353	      (void)mem_priority_stack_.emplace(NodeOutInfo(node, nodes_info_), node);
354	      return;
355	    }
356	    if (is_dfs_) {
357	      (void)normal_stack_.insert(normal_stack_.end(), node);
358	    } else {
359	      (void)normal_stack_.insert(normal_stack_.begin(), node);
360	    }
361	  }
362	
363	  bool Empty() {
364	    if (is_mem_priority_ && (!is_reverse_dfs_)) {
365	      return mem_priority_stack_.empty();
366	    }
367	    return normal_stack_.empty();
368	  }
369	
370	 private:
371	  bool is_mem_priority_;
372	  bool is_dfs_;
373	  bool is_reverse_dfs_;
374	  std::vector<NodeStatus> *nodes_info_;
375	  std::vector<NodePtr> normal_stack_;
376	  std::map<NodeOutInfo, NodePtr> mem_priority_stack_;
377	};
