379	void AssembleFuseFailReason(const std::vector<NodePtr> &nodes, const std::unordered_set<std::string> attr_set,
380	                            const std::string attr_key, std::string &reason_not_support) {
381	  std::stringstream failed_reason;
382	  failed_reason << "Fusion is not supported because there are multiple " << attr_key << " ";
383	  for (const auto &ele : attr_set) {
384	    failed_reason << "[" << ele << "]";
385	  }
386	  failed_reason << " between nodes ";
387	  for (const auto &node : nodes) {
388	    failed_reason << "[" << node->GetName() << "]";
389	  }
390	  reason_not_support += failed_reason.str();
391	  GELOGI("%s.", reason_not_support.c_str());
392	}
