431	graphStatus InheritSkFromOriginNodes(const std::vector<NodePtr> &ori_nodes, const std::vector<OpDescPtr> &fusion_ops) {
432	  const std::unordered_set<std::string> scopes = GetAttrStringSet(ori_nodes, ATTR_NAME_SUPER_KERNEL_SCOPE);
433	  const std::unordered_set<std::string> kernel_options = GetAttrStringSet(ori_nodes, ATTR_NAME_SUPER_KERNEL_OPTIONS);
434	  if (scopes.empty() && kernel_options.empty()) {
435	    return GRAPH_SUCCESS;
436	  }
437	  for (const auto &op_desc : fusion_ops) {
438	    if (!scopes.empty()) {
439	      GE_ASSERT_TRUE(AttrUtils::SetStr(op_desc, ATTR_NAME_SUPER_KERNEL_SCOPE, *scopes.begin()));
440	      GELOGD("set _super_kernel_scope %s for op %s", scopes.begin()->c_str(), op_desc->GetNamePtr());
441	    }
442	    if (!kernel_options.empty()) {
443	      GE_ASSERT_TRUE(AttrUtils::SetStr(op_desc, ATTR_NAME_SUPER_KERNEL_OPTIONS, *kernel_options.begin()));
444	      GELOGD("set _super_kernel_options %s for op %s", kernel_options.begin()->c_str(), op_desc->GetNamePtr());
445	    }
446	  }
447	  return GRAPH_SUCCESS;
448	}
