450	graphStatus InheritCoreNumFromOriginNodes(const std::vector<NodePtr> &ori_nodes,
451	                                          const std::vector<OpDescPtr> &fusion_ops) {
452	  std::unordered_set<std::string> origin_ai_core_nums;
453	  std::unordered_set<std::string> origin_vector_core_nums;
454	
455	  for (const auto &node : ori_nodes) {
456	    const auto &op_desc = node->GetOpDesc();
457	    const std::string *user_ai_core_num_op_ptr = AttrUtils::GetStr(op_desc, public_attr::OP_AI_CORE_NUM);
458	    if (user_ai_core_num_op_ptr != nullptr) {
459	      origin_ai_core_nums.emplace(*user_ai_core_num_op_ptr);
460	    }
461	    const std::string *user_vector_core_num_op_ptr = AttrUtils::GetStr(op_desc, public_attr::OP_VECTOR_CORE_NUM);
462	    if (user_vector_core_num_op_ptr != nullptr) {
463	      origin_vector_core_nums.emplace(*user_vector_core_num_op_ptr);
464	    }
465	  }
466	
467	  // 如果所有原始节点都没有设置核数，则不需要继承
468	  if (origin_ai_core_nums.empty() && origin_vector_core_nums.empty()) {
469	    GELOGI("No need to inherit core num, because origin nodes have no core num.");
470	    return GRAPH_SUCCESS;
471	  }
472	
473	  GELOGI("Begin to set core num for fusion ops.");
474	  for (const auto &op_desc : fusion_ops) {
475	    if (!origin_ai_core_nums.empty()) {
476	      GE_ASSERT_TRUE(AttrUtils::SetStr(op_desc, public_attr::OP_AI_CORE_NUM, *origin_ai_core_nums.begin()));
477	      GELOGD("set ai core num %s for op %s", origin_ai_core_nums.begin()->c_str(), op_desc->GetName().c_str());
478	    }
479	    if (!origin_vector_core_nums.empty()) {
480	      GE_ASSERT_TRUE(AttrUtils::SetStr(op_desc, public_attr::OP_VECTOR_CORE_NUM, *origin_vector_core_nums.begin()));
481	      GELOGD("set vector core num %s for op %s", origin_vector_core_nums.begin()->c_str(), op_desc->GetName().c_str());
482	    }
483	  }
484	  return GRAPH_SUCCESS;
485	}
