509	                                             std::deque<NodePtr> &candidates, const NodePtr node) const {
510	  const auto &subgraph_names = op_desc.GetSubgraphInstanceNames();
511	  auto name_iter = subgraph_names.rbegin();
512	  while (name_iter != subgraph_names.rend()) {
513	    const auto subgraph = GetSubgraph(*name_iter);
514	    if (subgraph != nullptr) {
515	      if ((graph_filter == nullptr) || graph_filter(*node, name_iter->c_str(), subgraph)) {
516	        auto subgraph_nodes = subgraph->GetDirectNode();
517	        (void)(candidates.insert(candidates.begin(), subgraph_nodes.begin(), subgraph_nodes.end()));
518	      }
519	    }
520	    ++name_iter;
521	  }
522	}
