694	/// Since there may be different input nodes
695	/// chosen by user in the same graph, special judgment is needed
696	bool ComputeGraphImpl::VectorInputNodePtrIsEqual(const std::vector<NodePtr> &left_nodes,
697	                                                 const std::vector<NodePtr> &right_nodes) const {
698	  const auto left_nodes_size = left_nodes.size();
699	  const auto right_nodes_size = right_nodes.size();
700	  if (left_nodes_size != right_nodes_size) {
701	    REPORT_INNER_ERR_MSG("E18888",
702	                         "Check failed with graph input_nodes_: "
703	                         "left inputNodes size %zu is different with right inputNodes size %zu .",
704	                         left_nodes_size, right_nodes_size);
705	    GELOGE(GRAPH_FAILED,
706	           "[Check][Param] failed with graph input_nodes_: "
707	           "left inputNodes size %zu is different with right inputNodes size %zu .",
708	           left_nodes_size, right_nodes_size);
709	    return false;
710	  }
711	  for (size_t j = 0UL; j < left_nodes_size; j++) {
712	    if ((left_nodes.at(j) == nullptr) || (right_nodes.at(j) == nullptr)) {
713	      REPORT_INNER_ERR_MSG("E18888", "left_nodes.at(%zu) or right_nodes.at(%zu) is nullptr", j, j);
714	      GELOGE(GRAPH_FAILED, "[Check][Param] left_nodes.at(%zu) or right_nodes.at(%zu) is nullptr", j, j);
715	      return false;
716	    }
717	    const auto &left_input_name = left_nodes.at(j)->GetName();
718	    const auto &right_input_name = right_nodes.at(j)->GetName();
719	    if (left_input_name != right_input_name) {
720	      REPORT_INNER_ERR_MSG("E18888",
721	                           "Check failed with graph input_nodes_: "
722	                           "left inputNode name %s is different with right inputNode name %s at inputNodes index %zu.",
723	                           left_input_name.c_str(), right_input_name.c_str(), j);
724	      GELOGE(GRAPH_FAILED,
725	             "[Check][Param] failed with graph input_nodes_: "
726	             "left inputNode name %s is different with right inputNode name %s at inputNodes index %zu.",
727	             left_input_name.c_str(), right_input_name.c_str(), j);
728	      return false;
729	    }
730	  }
731	  return true;
732	}
