734	bool ComputeGraphImpl::GraphMembersAreEqual(const ComputeGraphImpl &r_graph) const {
735	  return (IsEqual(this->sub_graph_.size(), r_graph.sub_graph_.size(), "graph.subgraphs_.size()") &&
736	          IsEqual(this->GetDirectNodesSize(), r_graph.GetDirectNodesSize(), "graph.nodes_.size()") &&
737	          VectorInputNodePtrIsEqual(this->input_nodes_, r_graph.input_nodes_) &&
738	          IsEqual(this->name_, r_graph.name_, "graph.name_") &&
739	          IsEqual(this->is_valid_flag_, r_graph.is_valid_flag_, "graph.is_valid_flag_") &&
740	          IsEqual(this->need_iteration_, r_graph.need_iteration_, "graph.need_iteration_") &&
741	          IsEqual(this->params_share_map_, r_graph.params_share_map_, "graph.params_share_map_") &&
742	          IsEqual(this->out_nodes_map_, r_graph.out_nodes_map_, "graph.out_nodes_map_") &&
743	          IsEqual(this->inputs_order_, r_graph.inputs_order_, "graph.inputs_order_") &&
744	          IsEqual(this->output_size_, r_graph.output_size_, "graph.output_size_") &&
745	          IsEqual(this->input_size_, r_graph.input_size_, "graph.input_size_") &&
746	          IsEqual(this->output_nodes_info_, r_graph.output_nodes_info_, "graph.output_nodes_info_"));
747	}
748	
749	bool ComputeGraphImpl::operator==(const ComputeGraphImpl &r_graph) const {
750	  // Firstly: Graph's members equal
751	  if ((!GraphMembersAreEqual(r_graph)) || (!GraphAttrsAreEqual(r_graph))) {
752	    return false;
753	  }
754	
755	  // Secondly: Node equal means the link relationship between node and node itself equal
756	  for (const auto &left_node : nodes_) {
757	    if (left_node == nullptr) {
758	      REPORT_INNER_ERR_MSG("E18888", "left_node is nullptr, graph:%s", this->GetName().c_str());
759	      GELOGE(GRAPH_FAILED, "[Check][Param] left_node is nullptr");
760	      return false;
761	    }
762	    const auto &node_name = left_node->GetName();
763	    // After TopologicalSorting, node order can change, so find node by name
764	    const auto &right_node = r_graph.FindNode(node_name);
765	    GE_IF_BOOL_EXEC(right_node == nullptr, REPORT_INNER_ERR_MSG("E18888", "left_node:%s not find in r_graph:%s",
766	                                                                node_name.c_str(), r_graph.GetName().c_str());
767	                    GELOGE(GRAPH_FAILED, "[Check][Param] right_node is NULL!!!"); return false);
768	    if (!((*right_node) == (*left_node))) {
769	      REPORT_INNER_ERR_MSG("E18888", "Compare graph failed, node:%s not equal.", node_name.c_str());
770	      GELOGE(GRAPH_FAILED, "[Compare][Graph] failed, node:%s not equal.", node_name.c_str());
771	      return false;
772	    }
773	  }
774	
775	  // Thirdly: Recursively determine whether the sub graphs are equal
776	  for (size_t i = 0UL; i < this->sub_graph_.size(); i++) {
777	    if (!((*((this->sub_graph_)[i])) == (*((r_graph.sub_graph_)[i])))) {
778	      return false;
779	    }
780	  }
781	  return true;
782	}
