869	bool ComputeGraphImpl::IsSupportFuse(const std::vector<NodePtr> &nodes, std::string &reason_not_support) {
870	  const std::unordered_set<std::string> origin_stream_labels = GetUserStreamLabels(nodes);
871	  if (origin_stream_labels.size() > 1U) {
872	    AssembleFuseFailReason(nodes, origin_stream_labels, public_attr::USER_STREAM_LABEL, reason_not_support);
873	    return false;
874	  }
875	
876	  const std::unordered_set<std::string> sk_scopes = GetAttrStringSet(nodes, ATTR_NAME_SUPER_KERNEL_SCOPE);
877	  if (sk_scopes.size() > 1U) {
878	    AssembleFuseFailReason(nodes, sk_scopes, ATTR_NAME_SUPER_KERNEL_SCOPE, reason_not_support);
879	    return false;
880	  }
881	
882	  const std::unordered_set<std::string> sk_options = GetAttrStringSet(nodes, ATTR_NAME_SUPER_KERNEL_OPTIONS);
883	  if (sk_options.size() > 1U) {
884	    AssembleFuseFailReason(nodes, sk_options, ATTR_NAME_SUPER_KERNEL_OPTIONS, reason_not_support);
885	    return false;
886	  }
887	  const std::unordered_set<std::string> aicore_num_options = GetAttrStringSet(nodes, public_attr::OP_AI_CORE_NUM);
888	  if (aicore_num_options.size() > 1U) {
889	    AssembleFuseFailReason(nodes, aicore_num_options, public_attr::OP_AI_CORE_NUM, reason_not_support);
890	    return false;
891	  }
892	
893	  const std::unordered_set<std::string> vectorcore_num_options =
894	      GetAttrStringSet(nodes, public_attr::OP_VECTOR_CORE_NUM);
895	  if (vectorcore_num_options.size() > 1U) {
896	    AssembleFuseFailReason(nodes, vectorcore_num_options, public_attr::OP_VECTOR_CORE_NUM, reason_not_support);
897	    return false;
898	  }
899	
900	  return true;
901	}
