903	std::vector<NodePtr> ComputeGraphImpl::FuseNodeKeepTopo(const std::vector<NodePtr> &ori_nodes,
904	                                                        const std::vector<OpDescPtr> &fusion_ops,
905	                                                        const ComputeGraphPtr &compute_graph) {
906	  std::string failed_reason;
907	  GE_WARN_ASSERT(IsSupportFuse(ori_nodes, failed_reason), failed_reason.c_str());
908	  if (InheritUserSteamLabelFromOriginNodes(ori_nodes, fusion_ops) != GRAPH_SUCCESS) {
909	    GELOGD("Abandoned to fuse nodes because inherit user stream label failed.");
910	    return {};
911	  }
912	  if (InheritSkFromOriginNodes(ori_nodes, fusion_ops) != GRAPH_SUCCESS) {
913	    GELOGI("Abandoned to fuse nodes because inherit sk attrs failed.");
914	    return {};
915	  }
916	  if (InheritCoreNumFromOriginNodes(ori_nodes, fusion_ops) != GRAPH_SUCCESS) {
917	    return {};
918	  }
919	
920	  auto min_id_node = NodeUtils::GetNodeWithMinimalId(ori_nodes);
921	  GE_ASSERT_NOTNULL(min_id_node);
922	  return InsertNodes(min_id_node, fusion_ops, compute_graph);
923	}
