985	  }
986	  if (std::find(input_nodes_.begin(), input_nodes_.end(), node) == input_nodes_.end()) {
987	    input_nodes_.push_back(node);
988	  }
989	  if (std::find(nodes_.begin(), nodes_.end(), node) == nodes_.end()) {
