1001	    REPORT_INNER_ERR_MSG("E18888", "The node ptr or opdesc should not be null.");
1002	    GELOGE(GRAPH_FAILED, "[Check][Param] The node ptr or opdesc should not be null.");
1003	    return nullptr;
1004	  }
1005	
1006	  bool already_have = false;
1007	  NodePtr result = node;
1008	  // [output_nodes_info_ : should not be null]
1009	  for (const auto &item : output_nodes_info_) {
1010	    if ((item.first->GetName() == node->GetName()) && (item.second == index)) {
1011	      already_have = true;
1012	      result = item.first;
1013	      break;
1014	    }
1015	  }
1016	
1017	  if (!already_have) {
1018	    output_nodes_info_.emplace_back(std::make_pair(node, index));
1019	    GELOGI("Push back node name:%s, index:%d, into output_nodes_info_.", node->GetName().c_str(), index);
1020	  }
1021	
1022	  if (std::find(nodes_.begin(), nodes_.end(), node) == nodes_.end()) {
1023	    GE_CHK_BOOL_EXEC(AddNode(node) != nullptr, return nullptr, "[Add][Node] failed");
1024	  }
1025	  return result;
1026	}
