1031	  for (const auto &in_anchor : node->GetAllInDataAnchors()) {
1032	    const auto out_anchor = in_anchor->GetPeerOutAnchor();
1033	    if ((out_anchor == nullptr) || (out_anchor->GetOwnerNodeBarePtr() == nullptr)) {
1034	      continue;
1035	    }
1036	    if ((out_anchor->GetOwnerNodeBarePtr()->GetType() == CONSTANT) ||
1037	        (out_anchor->GetOwnerNodeBarePtr()->GetType() == CONSTANTOP)) {
1038	      GE_CHK_BOOL_RET_STATUS(GraphUtils::RemoveEdge(out_anchor, in_anchor) == GRAPH_SUCCESS, GRAPH_FAILED,
1039	                             "[Remove][Edge] from const op %s failed.", out_anchor->GetOwnerNode()->GetName().c_str());
1040	      if (out_anchor->GetOwnerNode()->GetOutNodes().empty()) {
1041	        GELOGI("Remove const op %s.", out_anchor->GetOwnerNode()->GetName().c_str());
1042	        const auto iter = find(nodes_.begin(), nodes_.end(), out_anchor->GetOwnerNode());
1043	        if (iter != nodes_.end()) {
1044	          EraseFromNodeList(iter);
1045	        }
1046	      }
1047	    }
1048	  }
1049	  return GRAPH_SUCCESS;
1050	}
