1153	graphStatus ComputeGraphImpl::AddSubgraph(const std::string &name, const std::shared_ptr<ComputeGraph> &subgraph) {
1154	  if (subgraph == nullptr) {
1155	    REPORT_INNER_ERR_MSG("E18888", "Try to add a null subgraph, name %s", name.c_str());
1156	    GE_LOGE("[Check][Param] Try to add a null subgraph, name %s", name.c_str());
1157	    return GRAPH_PARAM_INVALID;
1158	  }
1159	  const auto parent_graph = subgraph->GetParentGraph();
1160	  if (parent_graph == nullptr) {
1161	    REPORT_INNER_ERR_MSG("E18888", "Try to add subgraph without parent graph, name %s", name.c_str());
1162	    GE_LOGE("[Get][Graph] Try to add subgraph without parent graph, name %s", name.c_str());
1163	    return GRAPH_PARAM_INVALID;
1164	  }
1165	  const auto parent_node = subgraph->GetParentNode();
1166	  if (parent_node == nullptr) {
1167	    REPORT_INNER_ERR_MSG("E18888", "Try to add a subgraph without parent node, name %s", name.c_str());
1168	    GE_LOGE("[Get][Node] Try to add a subgraph without parent node, name %s", name.c_str());
1169	    return GRAPH_PARAM_INVALID;
1170	  }
1171	  if (parent_node->GetOwnerComputeGraph() != parent_graph) {
1172	    REPORT_INNER_ERR_MSG("E18888",
1173	                         "Try to add a subgraph which parent node's graph is not equal to "
1174	                         "the subgraph's parent graph, subgraph name %s, parent node name %s",
1175	                         subgraph->GetName().c_str(), parent_graph->GetName().c_str());
1176	    GE_LOGE(
1177	        "[Check][Param] Try to add a subgraph which parent node's graph is not equal to "
1178	        "the subgraph's parent graph, subgraph name %s, parent node name %s",
1179	        subgraph->GetName().c_str(), parent_graph->GetName().c_str());
1180	    return GRAPH_PARAM_INVALID;
1181	  }
1182	  if (!this->parent_graph_.expired()) {
1183	    GELOGW("[Add][Subgraph] The subgraphs should only be added to the root graph");
1184	  }
1185	  if (name != subgraph->GetName()) {
1186	    GELOGW("[Add][Subgraph] The subgraph name %s is different with input %s", subgraph->GetName().c_str(),
1187	           name.c_str());
1188	  }
1189	  if (names_to_subgraph_.find(name) != names_to_subgraph_.end()) {
1190	    REPORT_INNER_ERR_MSG("E18888", "The subgraph %s existed", name.c_str());
1191	    GE_LOGE("[Check][Param] The subgraph %s existed", name.c_str());
1192	    return GRAPH_PARAM_INVALID;
1193	  }
1194	  sub_graph_.push_back(subgraph);
1195	  names_to_subgraph_[name] = subgraph;
1196	  return GRAPH_SUCCESS;
1197	}
