1199	GE_FUNC_DEV_VISIBILITY GE_FUNC_HOST_VISIBILITY void ComputeGraphImpl::RemoveSubgraph(const std::string &name) {
1200	  const std::map<std::string, af::ComputeGraphPtr>::const_iterator iter = names_to_subgraph_.find(name);
1201	  if (iter == names_to_subgraph_.cend()) {
1202	    return;
1203	  }
1204	  auto vec_iter = sub_graph_.begin();
1205	  while (vec_iter != sub_graph_.end()) {
1206	    if ((*vec_iter) == iter->second) {
1207	      (void)sub_graph_.erase(vec_iter);
1208	      break;
1209	    }
1210	    ++vec_iter;
1211	  }
1212	  (void)names_to_subgraph_.erase(iter);
1213	}
