1275	/// @brief Update input-mapping
1276	/// @param [in] input_mapping : index_of_cur_graph_node_input -> index_of_new_graph_node_input
1277	/// @return graphStatus
1278	graphStatus ComputeGraphImpl::UpdateInputMapping(const std::map<uint32_t, uint32_t> &input_mapping) {
1279	  for (auto &input : nodes_) {
1280	    if (input->GetType() == DATA) {
1281	      uint32_t cur_index = 0U;
1282	      if (!af::AttrUtils::GetInt(input->GetOpDescBarePtr(), ATTR_NAME_PARENT_NODE_INDEX, cur_index)) {
1283	        continue;
1284	      }
1285	      const auto iter = input_mapping.find(cur_index);
1286	      if (iter == input_mapping.end()) {
1287	        continue;
1288	      }
1289	      if (!af::AttrUtils::SetInt(input->GetOpDescBarePtr(), ATTR_NAME_PARENT_NODE_INDEX,
1290	                                 static_cast<int64_t>(iter->second))) {
1291	        REPORT_INNER_ERR_MSG("E18888", "set attr ATTR_NAME_PARENT_NODE_INDEX failed, op:%s.",
1292	                             input->GetOpDescBarePtr()->GetName().c_str());
1293	        GE_LOGE("[Call][SetInt] UpdateInputMapping failed: set attr ATTR_NAME_PARENT_NODE_INDEX failed, op:%s.",
1294	                input->GetOpDescBarePtr()->GetName().c_str());
1295	        return GRAPH_FAILED;
1296	      }
1297	    }
1298	  }
1299	
1300	  return GRAPH_SUCCESS;
1301	}
