1303	/// @brief Update output-mapping
1304	/// @param [in] output_mapping : index_of_cur_graph_node_output -> index_of_new_graph_node_output
1305	/// @return graphStatus
1306	graphStatus ComputeGraphImpl::UpdateOutputMapping(const std::map<uint32_t, uint32_t> &output_mapping) const {
1307	  const NodePtr net_output = FindFirstNodeMatchType(NETOUTPUT);
1308	  if (net_output == nullptr) {
1309	    REPORT_INNER_ERR_MSG("E18888", "UpdateOutputMapping failed: node type %s does not exist in graph.", NETOUTPUT);
1310	    GE_LOGE("[Get][NodeType] UpdateOutputMapping failed: node type %s does not exist in graph.", NETOUTPUT);
1311	    return GRAPH_FAILED;
1312	  }
1313	  const auto op_desc = net_output->GetOpDescBarePtr();
1314	  if (op_desc == nullptr) {
1315	    REPORT_INNER_ERR_MSG("E18888", "net output's op desc pr should not be null.");
1316	    GE_LOGE("[Get][OpDesc] UpdateOutputMapping failed: op_desc is NULL.");
1317	    return GRAPH_FAILED;
1318	  }
1319	
1320	  const size_t num = op_desc->GetAllInputsSize();
1321	  for (size_t i = 0UL; i < num; i++) {
1322	    GeTensorDesc tensor = op_desc->GetInputDesc(static_cast<uint32_t>(i));
1323	    uint32_t cur_index = 0U;
1324	    if (!af::AttrUtils::GetInt(tensor, ATTR_NAME_PARENT_NODE_INDEX, cur_index)) {
1325	      continue;
1326	    }
1327	    const auto iter = output_mapping.find(cur_index);
1328	    if (iter == output_mapping.end()) {
1329	      continue;
1330	    }
1331	    if (!af::AttrUtils::SetInt(tensor, ATTR_NAME_PARENT_NODE_INDEX, static_cast<int64_t>(iter->second))) {
1332	      REPORT_INNER_ERR_MSG("E18888", "op %s set %zu input tensor attr ATTR_NAME_PARENT_NODE_INDEX failed.",
1333	                           op_desc->GetName().c_str(), i);
1334	      GE_LOGE("[Set][Int] op %s set %zu input tensor attr ATTR_NAME_PARENT_NODE_INDEX failed.",
1335	              op_desc->GetName().c_str(), i);
1336	      return GRAPH_FAILED;
1337	    }
1338	    if (op_desc->UpdateInputDesc(static_cast<uint32_t>(i), tensor) != GRAPH_SUCCESS) {
1339	      REPORT_INNER_ERR_MSG("E18888", "op %s update %zu input_tensor failed.", op_desc->GetName().c_str(), i);
1340	      GE_LOGE("[Update][InputDesc] UpdateOutputMapping failed: update %zu input_tensor failed.", i);
1341	      return GRAPH_FAILED;
1342	    }
1343	  }
1344	
1345	  return GRAPH_SUCCESS;
1346	}
