1348	graphStatus ComputeGraphImpl::ReorderEventNodes(const ConstComputeGraphPtr &compute_graph) {
1349	  std::list<NodePtr> &node_list = nodes_;
1350	  for (const auto &node : GetDirectNode(compute_graph)) {
1351	    if ((strcmp(node->GetTypePtr(), RECV) == 0) || (strcmp(node->GetTypePtr(), RECV_NOTIFY) == 0)) {
1352	      const auto iter = find(node_list.cbegin(), node_list.cend(), node);
1353	      if (iter != node_list.cend()) {
1354	        (void)node_list.erase(iter);
1355	      }
1356	
1357	      const auto dst_iter = find(node_list.cbegin(), node_list.cend(), node->GetOutControlNodes().at(0UL));
1358	      (void)node_list.insert(dst_iter, node);
1359	    }
1360	    if ((strcmp(node->GetTypePtr(), SEND) == 0) || (strcmp(node->GetTypePtr(), SEND_NOTIFY) == 0)) {
1361	      const auto iter = find(node_list.cbegin(), node_list.cend(), node);
1362	      if (iter != node_list.cend()) {
1363	        (void)node_list.erase(iter);
1364	      }
1365	
1366	      auto src_iter = find(node_list.cbegin(), node_list.cend(), node->GetInControlNodes().at(0UL));
1367	      (void)node_list.insert(++src_iter, node);
1368	    }
1369	  }
1370	
1371	  return GRAPH_SUCCESS;
1372	}
