1374	graphStatus ComputeGraphImpl::InsertGraphEvents(const ConstComputeGraphPtr &compute_graph) {
1375	  auto status = ReorderEventNodes(compute_graph);
1376	  if (status != GRAPH_SUCCESS) {
1377	    REPORT_INNER_ERR_MSG("E18888", "Graph [%s] record event nodes failed, status:%u", name_.c_str(), status);
1378	    GELOGE(status, "[Reorder][EventNodes] failed for Graph:%s, status:%u", name_.c_str(), status);
1379	    return status;
1380	  }
1381	
1382	  // Partition subgraph
1383	  for (const auto &graph : sub_graph_) {
1384	    status = graph->ReorderEventNodes();
1385	    if (status != GRAPH_SUCCESS) {
1386	      REPORT_INNER_ERR_MSG("E18888", "ReorderEventNodes failed for SubGraph:%s, status:%u", graph->GetName().c_str(),
1387	                           status);
1388	      GELOGE(status, "[Reorder][EventNodes] failed for SubGraph:%s, status:%u", graph->GetName().c_str(), status);
1389	      return status;
1390	    }
1391	  }
1392	
1393	  std::vector<ComputeGraphPtr> subgraphs;
1394	  const auto nodes = AllGraphNodes(subgraphs, compute_graph);
1395	  for (size_t i = 0UL; i < nodes.size(); ++i) {
1396	    const NodePtr node = nodes.at(i);                          // [node: should not be null]
1397	    node->GetOpDescBarePtr()->SetId(static_cast<int64_t>(i));  // [node->GetOpDescBarePtr(): should not be null]
1398	  }
1399	
1400	  return GRAPH_SUCCESS;
1401	}
