1403	graphStatus ComputeGraphImpl::DFSTopologicalSorting(std::vector<NodePtr> &node_vec, const bool reverse,
1404	                                                    const ConstComputeGraphPtr &compute_graph) const {
1405	  GELOGI("Runing_Dfs_Sort, reverse: %d, graph: %s", reverse, name_.c_str());
1406	  std::vector<NodePtr> stack;
1407	  std::map<NodePtr, uint32_t> map_in_edge_num;
1408	  // Record the number of non data nodes but no input nodes
1409	  GE_CHK_BOOL_EXEC(SortNodes(stack, map_in_edge_num, compute_graph) == GRAPH_SUCCESS, return GRAPH_FAILED,
1410	                   "sort nodes failed");
1411	  const bool is_mem_priority = IsMemoryPriority();
1412	  std::vector<NodeStatus> nodes_info;
1413	  if (is_mem_priority) {
1414	    InitNodeStatus(compute_graph, nodes_info);
1415	  }
1416	  TopoSortStack topo_sort_stack(&nodes_info, is_mem_priority, true, reverse);
1417	  for (const auto &node : stack) {
1418	    topo_sort_stack.Push(node);
1419	  }
1420	  std::vector<NodePtr> out_nodes;
1421	  const auto stack_push = [&reverse, &topo_sort_stack](std::vector<NodePtr> &tmp_out_nodes) {
1422	    if (reverse) {
1423	      std::reverse(tmp_out_nodes.begin(), tmp_out_nodes.end());
1424	    }
1425	    for (const auto &node : tmp_out_nodes) {
1426	      topo_sort_stack.Push(node);
1427	    }
1428	    tmp_out_nodes.clear();
1429	  };
1430	  // Only data nodes here
1431	  while (!topo_sort_stack.Empty()) {
1432	    const NodePtr node = topo_sort_stack.Pop();
1433	    node_vec.push_back(node);
1434	    GE_CHECK_NOTNULL(node->GetOpDescBarePtr());
1435	    GELOGD("node_vec.push_back %s", node->GetOpDescBarePtr()->GetName().c_str());
1436	    for (const auto &anchor : node->GetAllOutDataAnchors()) {
1437	      GE_CHECK_NOTNULL(anchor);
1438	      for (const auto &peer_in_anchor : anchor->GetPeerInDataAnchorsPtr()) {
1439	        GE_CHECK_NOTNULL(peer_in_anchor);
1440	        GetOutNodesFromAnchor(peer_in_anchor, map_in_edge_num, out_nodes);
1441	      }
1442	      stack_push(out_nodes);
1443	      for (const auto &peer_in_anchor : anchor->GetPeerInControlAnchors()) {
1444	        GE_CHECK_NOTNULL(peer_in_anchor);
1445	        GetOutNodesFromAnchor(peer_in_anchor, map_in_edge_num, out_nodes);
1446	      }
1447	      stack_push(out_nodes);
1448	    }
1449	    GE_IF_BOOL_EXEC(
1450	        node->GetOutControlAnchor() != nullptr, for (const AnchorPtr peer_in_anchor
1451	                                                     : node->GetOutControlAnchor()->GetPeerAnchors()) {
1452	          GE_CHECK_NOTNULL(peer_in_anchor);
1453	          GetOutNodesFromAnchor(peer_in_anchor, map_in_edge_num, out_nodes);
1454	        } stack_push(out_nodes);)
1455	  }
1456	
1457	  return GRAPH_SUCCESS;
1458	}
1459	
1460	graphStatus ComputeGraphImpl::StableRDFSTopologicalSorting(std::vector<NodePtr> &node_vec, const bool reverse,
1461	                                                           const ConstComputeGraphPtr &compute_graph) const {
1462	  (void)reverse;
1463	  GELOGI("Runing_Stable_Reverse_Dfs_Sort: %s", name_.c_str());
1464	  std::vector<NodeStatus> nodes_info;
1465	  InitNodeStatus(compute_graph, nodes_info);
1466	
1467	  for (const auto &node : compute_graph->GetDirectNode()) {
1468	    GE_CHECK_NOTNULL(node);
1469	    GE_CHECK_NOTNULL(node->GetOpDesc());
1470	    GE_CHECK_NOTNULL(node->GetOpDescBarePtr());
1471	    // id作为索引前面的init初始化保证了一定是有效的, walked的节点不入栈
1472	    if (nodes_info[node->GetOpDesc()->GetId()].status == WalkStatus::kWalked) {
1473	      continue;
1474	    }
1475	    // 按照原有的nodes的topo顺序来入栈
1476	    std::vector<Node *> stack = {node.get()};
1477	    while (!stack.empty()) {
1478	      const auto current = stack.back();
1479	      NodeStatus &reverse_dfs_node_info = nodes_info[current->GetOpDesc()->GetId()];
1480	      if (reverse_dfs_node_info.status == WalkStatus::kNotWalked) {
1481	        reverse_dfs_node_info.status = WalkStatus::kWalking;
1482	        // 获取输入节点，反向遍历
1483	        const auto in_all_nodes = current->GetInNodesPtr();
1484	        if (in_all_nodes.empty()) {
1485	          continue;
1486	        }
1487	        std::vector<Node *> in_nodes_has_not_been_walked;
1488	        in_nodes_has_not_been_walked.reserve(in_all_nodes.size());
1489	        for (const auto in_node : in_all_nodes) {
1490	          if (nodes_info[in_node->GetOpDesc()->GetId()].status == WalkStatus::kNotWalked) {
1491	            in_nodes_has_not_been_walked.push_back(in_node);
1492	          }
1493	        }
1494	
1495	        auto cmp = [](const Node *lhs, const Node *rhs) {
1496	          // not null
1497	          return lhs->GetOpDescBarePtr()->GetId() > rhs->GetOpDescBarePtr()->GetId();
1498	        };
1499	        // 输入节点的排序使用原始的顺序，可以保证原有topo如果满足当前图的遍历关系，最大程度的保留下来
1500	        std::set<Node *, decltype(cmp)> input_nodes{in_nodes_has_not_been_walked.begin(),
1501	                                                    in_nodes_has_not_been_walked.end(), cmp};
1502	        stack.insert(stack.end(), input_nodes.cbegin(), input_nodes.cend());
1503	      } else {
1504	        stack.pop_back();
1505	        if (reverse_dfs_node_info.status != WalkStatus::kWalking) {
1506	          continue;
1507	        }
1508	        reverse_dfs_node_info.status = WalkStatus::kWalked;
1509	        node_vec.emplace_back(current->shared_from_this());
1510	        GE_CHECK_NOTNULL(current->GetOpDescBarePtr());
1511	        GELOGD("node_vec.push_back %s", current->GetOpDescBarePtr()->GetName().c_str());
1512	      }
1513	    }
1514	  }
1515	
1516	  return GRAPH_SUCCESS;
1517	}
