1529	graphStatus ComputeGraphImpl::RDFSTopologicalSortingV2(std::vector<NodePtr> &node_vec, const bool reverse,
1530	                                                       const ConstComputeGraphPtr &compute_graph) const {
1531	  (void)reverse;
1532	  GELOGI("Running_Reverse_Dfs_Sort_V2: %s", name_.c_str());
1533	  std::vector<NodeStatus> nodes_info;
1534	  InitNodeStatus(compute_graph, nodes_info);
1535	  NodeCmp cmp(&nodes_info);
1536	
1537	  std::vector<NodePtr> initial_vec;
1538	  if (RDFSCoreSort(initial_vec, nodes_info, compute_graph, cmp) != GRAPH_SUCCESS) {
1539	    return GRAPH_FAILED;
1540	  }
1541	
1542	  for (size_t i = 0UL; i < initial_vec.size(); ++i) {
1543	    initial_vec[i]->GetOpDescBarePtr()->SetId(static_cast<int64_t>(i));
1544	  }
1545	
1546	  std::vector<int64_t> branch_widths(initial_vec.size(), 0);
1547	  for (auto it = initial_vec.rbegin(); it != initial_vec.rend(); ++it) {
1548	    const auto &node = *it;
1549	    const auto id = static_cast<size_t>(node->GetOpDesc()->GetId());
1550	    int64_t width = GetNodeInputCount(node);
1551	    for (const auto &in_node : node->GetInAllNodes()) {
1552	      const auto in_id = static_cast<size_t>(in_node->GetOpDesc()->GetId());
1553	      width = std::max(width, branch_widths[in_id]);
1554	    }
1555	    branch_widths[id] = width;
1556	  }
1557	
1558	  std::fill(nodes_info.begin(), nodes_info.end(), NodeStatus{0U, WalkStatus::kNotWalked});
1559	
1560	  const NodeCmpV2 cmp_v2(&nodes_info, &branch_widths);
1561	  return RDFSCoreSort(node_vec, nodes_info, compute_graph, cmp_v2);
1562	}
