1564	graphStatus ComputeGraphImpl::BFSTopologicalSorting(std::vector<NodePtr> &node_vec, const bool reverse,
1565	                                                    const ConstComputeGraphPtr &compute_graph) const {
1566	  GELOGI("Runing_Bfs_Sort: %s", name_.c_str());
1567	  (void)reverse;
1568	  const bool is_mem_priority = IsMemoryPriority();
1569	  std::vector<NodeStatus> nodes_info;
1570	  if (is_mem_priority) {
1571	    InitNodeStatus(compute_graph, nodes_info);
1572	  }
1573	  TopoSortStack topo_sort_stack(&nodes_info, is_mem_priority);
1574	  std::vector<NodePtr> stack_input;
1575	  std::map<std::string, NodePtr> breadth_node_map;
1576	  std::map<NodePtr, uint32_t> map_in_edge_num;
1577	  // Record the number of non data nodes but no input nodes
1578	  GE_CHK_BOOL_EXEC(SortNodes(stack_input, map_in_edge_num, compute_graph) == GRAPH_SUCCESS, return GRAPH_FAILED,
1579	                   "sort nodes failed");
1580	
1581	  // Only data nodes here
1582	  while ((!stack_input.empty()) || (!topo_sort_stack.Empty())) {
1583	    NodePtr node = nullptr;
1584	    if (!topo_sort_stack.Empty()) {
1585	      node = topo_sort_stack.Pop();
1586	    } else {
1587	      node = stack_input.back();
1588	      stack_input.pop_back();
1589	    }
1590	
1591	    node_vec.push_back(node);
1592	    GE_CHECK_NOTNULL(node->GetOpDescBarePtr());
1593	    GELOGD("node_vec.push_back %s", node->GetOpDescBarePtr()->GetName().c_str());
1594	    (void)CollectBreadthOutNode(node, map_in_edge_num, breadth_node_map);
1595	
1596	    for (const auto &name_node : breadth_node_map) {
1597	      (void)topo_sort_stack.Push(name_node.second);
1598	    }
1599	    breadth_node_map.clear();
1600	  }
1601	  return GRAPH_SUCCESS;
1602	}
