1638	graphStatus ComputeGraphImpl::GetRetvalOutputInfo(
1639	    const af::NodePtr &node, std::map<int32_t, af::ComputeGraphImpl::RetvalInfo> &retval_node_index_map) {
1640	  GE_CHECK_NOTNULL(node);
1641	  GE_CHECK_NOTNULL(node->GetOpDesc());
1642	  int64_t output_index = 0;
1643	  GE_ASSERT_TRUE(AttrUtils::GetInt(node->GetOpDesc(), RETVAL_ATTR_NAME_INDEX, output_index),
1644	                 "Get Attr:%s from op:%s(%s) failed", RETVAL_ATTR_NAME_INDEX.c_str(), node->GetName().c_str(),
1645	                 node->GetType().c_str());
1646	  GE_ASSERT_TRUE((retval_node_index_map.count(output_index) <= 0),
1647	                 "Attr:%s from op:%s(%s), value:%ld duplicate with other node, check invalid",
1648	                 RETVAL_ATTR_NAME_INDEX.c_str(), node->GetName().c_str(), node->GetType().c_str(), output_index);
1649	  int32_t parent_node_index = -1;
1650	  (void)AttrUtils::GetInt(node->GetOpDesc(), ATTR_NAME_PARENT_NODE_INDEX, parent_node_index);
1651	  InDataAnchorPtr in_data_anchor = node->GetInDataAnchor(0);
1652	  GE_CHECK_NOTNULL(in_data_anchor);
1653	  GE_CHECK_NOTNULL(in_data_anchor->GetPeerOutAnchor());
1654	  int32_t src_node_index = in_data_anchor->GetPeerOutAnchor()->GetIdx();
1655	  NodePtr src_node_ptr = in_data_anchor->GetPeerOutAnchor()->GetOwnerNode();
1656	  retval_node_index_map[output_index] = {src_node_ptr, src_node_index, parent_node_index};
1657	  GELOGD("retval node %s, index %d", src_node_ptr->GetNamePtr(), src_node_index);
1658	  // if user targets include retval node,delete it from set and insert its input node instead
1659	  // better to GetInNodes here
1660	  const auto iter = targets_.find(node);
1661	  if (iter != targets_.end()) {
1662	    targets_.erase(iter);
1663	    targets_.insert(src_node_ptr);
1664	    GELOGI("Node [%s] is in user def targets, do not output result to user!", node->GetName().c_str());
1665	  }
1666	  is_include_special_node_ = true;
1667	  return GRAPH_SUCCESS;
1668	}
