1670	graphStatus ComputeGraphImpl::CollectOutputNode(const ComputeGraphPtr &compute_graph,
1671	                                                std::vector<af::ComputeGraphImpl::RetvalInfo> &output_nodes_info) {
1672	  for (NodePtr &node : GetDirectNode(compute_graph)) {
1673	    Status ret = SUCCESS;
1674	    if ((node->GetOpDesc() != nullptr) && (node->GetOpDesc()->HasAttr(RETVAL_ATTR_NAME_INDEX))) {
1675	      /// Set the output according to the Retval operator,
1676	      /// identify by whether there is an index parameter
1677	      ret = GetRetvalOutputInfo(node, retval_node_index_map_);
1678	    }
1679	    GE_ASSERT_SUCCESS(ret, "[Get][RetvalOutputInfo] for node:%s failed", node->GetName().c_str());
1680	  }
1681	  GELOGI("Get retval node size:%zu.", retval_node_index_map_.size());
1682	  std::vector<RetvalInfo> out_nodes_tmp;
1683	  /// The Netoutput output is determined by Retval, and the input order
1684	  /// of Netoutput is sorted according to the index value of Retval.
1685	  for (auto &it : retval_node_index_map_) {
1686	    out_nodes_tmp.push_back(it.second);
1687	  }
1688	
1689	  for (auto &ele : GetGraphOutNodesInfo()) {
1690	    const auto iter = targets_.find(ele.first);
1691	    if (iter != targets_.end()) {
1692	      GELOGI("User set out node [%s] is found in user def targets, out node is prior!", ele.first->GetName().c_str());
1693	      targets_.erase(iter);
1694	    }
1695	
1696	    auto op_desc = ele.first->GetOpDesc();
1697	    GE_CHECK_NOTNULL(op_desc);
1698	    int32_t parent_index = -1;
1699	    auto output_desc = op_desc->MutableOutputDesc(ele.second);
1700	    GE_ASSERT_NOTNULL(output_desc, "[Get][OutputDesc]Can not find output tensor desc from node:%s, index %d",
1701	                      op_desc->GetName().c_str(), ele.second);
1702	    (void)af::AttrUtils::GetInt(output_desc, ATTR_NAME_PARENT_NODE_INDEX, parent_index);
1703	    output_nodes_info.push_back({ele.first, ele.second, parent_index});
1704	  }
1705	  GELOGI("Output node set by user or leaf node, size:%zu.", output_nodes_info.size());
1706	  for (auto &ele : out_nodes_tmp) {
1707	    // add member, no need to remove duplicated because we need to keep all edges
1708	    output_nodes_info.push_back(ele);
1709	  }
1710	  GELOGI("Get output node, size:%zu.", output_nodes_info.size());
1711	
1712	  GE_ASSERT_SUCCESS(CheckOutputNodeInfo(output_nodes_info));
1713	  return GRAPH_SUCCESS;
1714	}
