1774	graphStatus ComputeGraphImpl::AddDataEdgesForNetOutput(
1775	    const ComputeGraphPtr &compute_graph, const af::NodePtr &net_out_node,
1776	    const std::vector<af::ComputeGraphImpl::RetvalInfo> &output_nodes_info) {
1777	  int32_t net_input_index = 0;
1778	  for (auto &item : output_nodes_info) {
1779	    NodePtr src_node = item.output_node;
1780	    auto src_output_index = item.node_output_index;
1781	    GE_CHECK_NOTNULL(src_node);
1782	
1783	    auto net_in_data_anchor = net_out_node->GetInDataAnchor(net_input_index);
1784	    // 判断是否已经连过边，防止重复连边
1785	    if ((net_in_data_anchor != nullptr) &&
1786	        src_node->GetOutDataAnchor(src_output_index)->IsLinkedWith(net_in_data_anchor)) {
1787	      net_input_index++;
1788	      continue;
1789	    }
1790	
1791	    // 判断是否别的节点已经连边，如果连了，则断开
1792	    if ((net_in_data_anchor != nullptr) && (net_in_data_anchor->GetPeerOutAnchor()) != nullptr) {
1793	      GELOGI("Netoutput node input index %d has been linked, unlink it first.", net_input_index);
1794	      GE_ASSERT_SUCCESS(GraphUtils::RemoveEdge(net_in_data_anchor->GetPeerOutAnchor(), net_in_data_anchor),
1795	                        "[Remove][Edge] failed, netoutput %s input index %d.", net_out_node->GetName().c_str(),
1796	                        net_input_index);
1797	    }
1798	
1799	    // 如果连着控制边，则断开，因为后面会连数据边
1800	    const auto src_control_anchor = src_node->GetOutControlAnchor();
1801	    const auto dst_control_anchor = net_out_node->GetInControlAnchor();
1802	    if ((src_control_anchor != nullptr) && (dst_control_anchor != nullptr) &&
1803	        src_control_anchor->IsLinkedWith(dst_control_anchor)) {
1804	      GE_ASSERT_SUCCESS(GraphUtils::RemoveEdge(src_control_anchor, dst_control_anchor),
1805	                        "[Remove][Edge] remove control edge failed, netoutput %s.", net_out_node->GetName().c_str());
1806	    }
1807	
1808	    GE_ASSERT_SUCCESS(net_out_node->AddLinkFrom(net_input_index, src_node, src_output_index),
1809	                      "Add edge between op:%s(%s)(index:%u) and op:%s(%s)(index:%d) failed",
1810	                      src_node->GetName().c_str(), src_node->GetType().c_str(), item.node_output_index,
1811	                      net_out_node->GetName().c_str(), net_out_node->GetType().c_str(), net_input_index);
1812	
1813	    GELOGD("AddEdge to output node, src name:%s, src index:%d, dst index:%d.", src_node->GetName().c_str(),
1814	           item.node_output_index, net_input_index);
1815	    net_input_index++;
1816	  }
1817	
1818	  // 对于其他多连的数据输入，断开连边
1819	  for (int32_t i = net_input_index; i < static_cast<int32_t>(net_out_node->GetInDataNodesSize()); i++) {
1820	    auto peer_out_anchor = net_out_node->GetInDataAnchor(i)->GetPeerOutAnchor();
1821	    if (peer_out_anchor != nullptr) {
1822	      GELOGI("Netoutput node input index %d has been linked, unlink it.", i);
1823	      GE_ASSERT_SUCCESS(GraphUtils::RemoveEdge(peer_out_anchor, net_out_node->GetInDataAnchor(i)),
1824	                        "[Remove][Edge] failed, netoutput %s input index %d.", net_out_node->GetName().c_str(), i);
1825	    }
1826	  }
1827	  GE_ASSERT_SUCCESS(RemoveUnusedRetvalNode(compute_graph), "[Remove][UnusedNode] from graph:%s failed.",
1828	                    GetName().c_str());
1829	  // Add true stream, netoutput is 0
1830	  GE_IF_BOOL_EXEC(
1831	      !af::AttrUtils::SetInt(net_out_node->GetOpDesc(), ATTR_NAME_TRUE_BRANCH_STREAM, 0),
1832	      REPORT_INNER_ERR_MSG("E19999", "Set Attr:%s to op:%s(%s) failed", ATTR_NAME_TRUE_BRANCH_STREAM.c_str(),
1833	                           net_out_node->GetName().c_str(), net_out_node->GetType().c_str());
1834	      GELOGE(af::INTERNAL_ERROR, "[Set][Attr] %s to op:%s(%s) failed", ATTR_NAME_TRUE_BRANCH_STREAM.c_str(),
1835	             net_out_node->GetName().c_str(), net_out_node->GetType().c_str());
1836	      return af::INTERNAL_ERROR);
1837	  return GRAPH_SUCCESS;
1838	}
