1840	graphStatus ComputeGraphImpl::RemoveUnusedRetvalNode(const ComputeGraphPtr &compute_graph) {
1841	  std::vector<af::NodePtr> node_to_delete;
1842	  // Delete _Retval operator.
1843	  for (auto &node : GetDirectNode(compute_graph)) {
1844	    GE_IF_BOOL_EXEC(node->GetOpDesc() == nullptr, GELOGW("Node OpDesc is nullptr"); continue);
1845	    bool need_be_deleted = (node->GetInDataNodesSize() != 0) && (node->GetOutDataNodesSize() == 0) &&
1846	                           (node->GetOpDesc()->HasAttr(RETVAL_ATTR_NAME_INDEX));
1847	    if (need_be_deleted) {
1848	      node_to_delete.push_back(node);
1849	    }
1850	  }
1851	  for (NodePtr &node : node_to_delete) {
1852	    const auto iter = targets_.find(node);
1853	    if (iter != targets_.end()) {
1854	      GELOGI("node[%s] is in user set targets.so do not remove!", node->GetName().c_str());
1855	      continue;
1856	    }
1857	    GE_ASSERT_SUCCESS(RemoveNode(node), "Remove node:%s(%s) from graph:%s failed", node->GetName().c_str(),
1858	                      node->GetType().c_str(), GetName().c_str());
1859	  }
1860	  return GRAPH_SUCCESS;
1861	}
