  graphStatus DoTopologicalSorting(const ConstComputeGraphPtr &compute_graph, TopoSortingMode sorting_mode,
                                   bool dfs_reverse);

 private:
  // 该private用于生成Netoutput节点
  struct RetvalInfo {
    NodePtr output_node;
