55	graphStatus Node::NodeImpl::Init(const NodePtr &node) {
56	  if (has_init_) {
57	    return GRAPH_SUCCESS;
58	  }
59	  GE_CHK_BOOL_EXEC(op_ != nullptr, REPORT_INNER_ERR_MSG("E18888", "original OpDesc is nullptr");
60	                   return GRAPH_FAILED, "[Check][Param] original OpDesc is nullptr");
61	  size_t size = op_->GetAllInputsSize();
62	  in_data_anchors_.reserve(size);
63	  for (size_t i = 0UL; i < size; i++) {
64	    const std::shared_ptr<InDataAnchor> anchor = ComGraphMakeShared<InDataAnchor>(node, i);
65	    if (anchor == nullptr) {
66	      REPORT_INNER_ERR_MSG("E18888", "Current in_data_anchor is null, malloc shared_ptr failed.");
67	      GELOGE(GRAPH_FAILED, "[Create][InDataAnchor] Current in_data_anchor is null, malloc shared_ptr failed.");
68	      return GRAPH_FAILED;
69	    }
70	    in_data_anchors_.push_back(anchor);
71	  }
72	  size = op_->GetOutputsSize();
73	  out_data_anchors_.reserve(size);
74	  for (size_t i = 0UL; i < size; i++) {
75	    const std::shared_ptr<OutDataAnchor> anchor = ComGraphMakeShared<OutDataAnchor>(node, i);
76	    if (anchor == nullptr) {
77	      REPORT_INNER_ERR_MSG("E18888", "Current out_data_anchor is null, malloc shared_ptr failed.");
78	      GELOGE(GRAPH_FAILED, "[Create][OutDataAnchor] Current out_data_anchor is null, malloc shared_ptr failed.");
79	      return GRAPH_FAILED;
80	    }
81	    out_data_anchors_.push_back(anchor);
82	  }
83	  in_control_anchor_ = ComGraphMakeShared<InControlAnchor>(node, -1);
84	  out_control_anchor_ = ComGraphMakeShared<OutControlAnchor>(node, -1);
85	  if ((in_control_anchor_ == nullptr) || (out_control_anchor_ == nullptr)) {
86	    REPORT_INNER_ERR_MSG("E18888",
87	                         "Current in_control_anchor or out_control_anchor is null, malloc shared_ptr failed.");
88	    GELOGE(GRAPH_FAILED,
89	           "[Create][ControlAnchor] Current in_control_anchor or out_control_anchor is null, "
90	           "malloc shared_ptr failed.");
91	    return GRAPH_FAILED;
92	  }
93	  has_init_ = true;
94	  return GRAPH_SUCCESS;
95	}
